-- Sprint 68: Support Ticket orchestration completion readbacks.
-- No ticket mutation, workflow dispatch, approval decision, external send/write,
-- provider call, credential payload read, spend change, deploy/publish, or secrets.

CREATE OR REPLACE VIEW `v_platform_orchestration_support_ticket_external_delivery_readiness` AS
SELECT
  'support_ticket_external_delivery_orchestrator' AS `plugin_key`,
  (SELECT COUNT(*) FROM `platform_orchestration_stages` WHERE `plugin_key`='support_ticket_external_delivery_orchestrator') AS `stage_count`,
  (SELECT COUNT(*) FROM `platform_orchestration_edges` WHERE `plugin_key`='support_ticket_external_delivery_orchestrator') AS `edge_count`,
  7 AS `expected_stage_count`,
  6 AS `expected_edge_count`,
  (SELECT COUNT(*) FROM `credential_bindings`) AS `credential_binding_rows`,
  (SELECT COUNT(*) FROM `credential_intake_sessions`) AS `credential_intake_rows`,
  (SELECT COUNT(*) FROM `external_delivery_provider_adapter_enablement_proposals`) AS `adapter_enablement_proposal_rows`,
  (SELECT COUNT(*) FROM `external_delivery_provider_adapter_readiness_checklists`) AS `adapter_readiness_checklist_rows`,
  (SELECT COUNT(*) FROM `external_delivery_provider_adapter_readiness_decisions`) AS `adapter_readiness_decision_rows`,
  (SELECT COUNT(*) FROM `external_delivery_provider_send_mode_policy_registry`) AS `send_mode_policy_rows`,
  (SELECT COUNT(*) FROM `ticket_workflow_links` WHERE `relationship` LIKE 'external_%') AS `external_workflow_link_rows`,
  CASE WHEN (SELECT COUNT(*) FROM `platform_orchestration_stages` WHERE `plugin_key`='support_ticket_external_delivery_orchestrator') >= 7
         AND (SELECT COUNT(*) FROM `platform_orchestration_edges` WHERE `plugin_key`='support_ticket_external_delivery_orchestrator') >= 6
       THEN 'ready_readonly_external_delivery_graph'
       ELSE 'degraded_external_delivery_graph_incomplete'
  END AS `readiness_status`,
  JSON_OBJECT('no_provider_call',true,'no_credential_payload_read',true,'no_external_send',true,'no_external_write',true,'no_deploy',true,'no_publish',true,'secrets_included',false) AS `safety_json`,
  JSON_OBJECT('mode','read_only','external_send_performed',false,'secrets_included',false) AS `evidence_json`,
  0 AS `secrets_included`;

