ON DUPLICATE KEY UPDATE `display_name`=VALUES(`display_name`),`domain_key`=VALUES(`domain_key`),`plugin_type`=VALUES(`plugin_type`),`manifest_json`=VALUES(`manifest_json`),`safety_contract_json`=VALUES(`safety_contract_json`),`status`=VALUES(`status`),`notes`=VALUES(`notes`),`updated_at`=CURRENT_TIMESTAMP;

